# CASO-LIM-012 · status_action (política N1)
# DEFECT: 429 y 500 van a fail_client; 503 no contemplado
def status_action(code):
    if code == 200:
        return "use_body"
    if code == 404:
        return "missing"
    if code in (429, 500):
        return "fail_client"
    if code == 400:
        return "fix_client"
    return "unknown"
for code in [200, 404, 429, 400, 500, 503]:
    print(code, status_action(code))
print('ok', True)

